css:
.t26-blot-row{
  --t26-blot-up:#3ddc97;--t26-blot-dn:#ff5d73;--t26-blot-tx:#e7ebf5;--t26-blot-dim:#79839b;
  --t26-blot-line:rgba(255,255,255,.075);
  --t26-blot-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  box-sizing:border-box;width:100%;padding:9px 10px 8px;border-radius:10px;
  background:linear-gradient(180deg,#141824 0%,#0d1017 100%);
  border:1px solid var(--t26-blot-line);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.045);
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--t26-blot-tx);display:flex;flex-direction:column;gap:5px;
}
.t26-blot-row-top{display:flex;align-items:center;gap:6px;font-size:9px;letter-spacing:.14em;color:var(--t26-blot-dim);}
.t26-blot-row-ttl{font-weight:700;color:#aab3c7;}
.t26-blot-row-live{display:inline-flex;align-items:center;gap:4px;color:var(--t26-blot-up);letter-spacing:.1em;}
.t26-blot-row-pip{width:5px;height:5px;border-radius:50%;background:var(--t26-blot-up);animation:t26-blot-row-pulse 1.9s ease-in-out infinite;}
.t26-blot-row-clock{margin-left:auto;font-family:var(--t26-blot-mono);font-variant-numeric:tabular-nums;letter-spacing:.03em;color:#8d97ad;}
.t26-blot-row-head,.t26-blot-row-r{display:grid;grid-template-columns:1fr 40px 52px 58px 34px;gap:4px;align-items:center;}
.t26-blot-row-head{font-size:8px;letter-spacing:.11em;color:#5f6980;padding:0 4px 4px;border-bottom:1px solid var(--t26-blot-line);}
.t26-blot-row-hnum,.t26-blot-row-hven{text-align:right;}
.t26-blot-row-body{display:flex;flex-direction:column;gap:1px;padding-top:2px;}
.t26-blot-row-r{padding:3px 4px;border-radius:5px;transition:background .18s ease;outline:none;}
.t26-blot-row-r:hover{background:rgba(255,255,255,.045);}
.t26-blot-row-r:focus-visible{background:rgba(255,255,255,.07);box-shadow:0 0 0 1.5px #6aa8ff;}
.t26-blot-row-sym{display:flex;align-items:center;gap:5px;font-size:11px;font-weight:650;letter-spacing:.01em;}
.t26-blot-row-sd{display:inline-flex;align-items:center;justify-content:center;width:13px;height:13px;border-radius:3px;font-size:9px;font-weight:800;font-style:normal;flex:none;}
.t26-blot-row-buy{background:rgba(61,220,151,.16);color:var(--t26-blot-up);box-shadow:inset 0 0 0 1px rgba(61,220,151,.32);}
.t26-blot-row-sell{background:rgba(255,93,115,.16);color:var(--t26-blot-dn);box-shadow:inset 0 0 0 1px rgba(255,93,115,.32);}
.t26-blot-row-c{font-family:var(--t26-blot-mono);font-variant-numeric:tabular-nums;font-size:10px;text-align:right;border-radius:3px;padding:1px 2px;}
.t26-blot-row-qty{color:#98a2b8;}
.t26-blot-row-px{color:#e3e9f6;font-weight:600;}
.t26-blot-row-ven{font-size:8px;color:#6d778e;letter-spacing:.05em;}
.t26-blot-row-up{color:var(--t26-blot-up);}
.t26-blot-row-dn{color:var(--t26-blot-dn);}
.t26-blot-row-fu{animation:t26-blot-row-fu .7s ease-out;}
.t26-blot-row-fd{animation:t26-blot-row-fd .7s ease-out;}
.t26-blot-row-foot{display:flex;align-items:center;justify-content:space-between;margin-top:1px;padding-top:5px;border-top:1px solid var(--t26-blot-line);font-size:9px;color:var(--t26-blot-dim);}
.t26-blot-row-net{font-family:var(--t26-blot-mono);font-variant-numeric:tabular-nums;letter-spacing:.03em;color:#8d97ad;}
.t26-blot-row-netv{font-weight:700;}
@keyframes t26-blot-row-pulse{0%,100%{opacity:1;transform:scale(1);}50%{opacity:.35;transform:scale(.7);}}
@keyframes t26-blot-row-fu{0%{background:rgba(61,220,151,.34);}100%{background:rgba(61,220,151,0);}}
@keyframes t26-blot-row-fd{0%{background:rgba(255,93,115,.32);}100%{background:rgba(255,93,115,0);}}
@media (prefers-reduced-motion:reduce){
  .t26-blot-row-pip{animation:none;}
  .t26-blot-row-r{transition:none;}
  .t26-blot-row-fu,.t26-blot-row-fd{animation:none;}
}

js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows=Array.prototype.slice.call(root.querySelectorAll('.t26-blot-row-r'));
var clock=root.querySelector('.t26-blot-row-clock');
var netEl=root.querySelector('.t26-blot-row-netv');
var t=52327;
function two(n){return n<10?'0'+n:''+n;}
function clockTxt(){var h=Math.floor(t/3600)%24,m=Math.floor(t/60)%60,s=t%60;return two(h)+':'+two(m)+':'+two(s);}
function money(n){return Math.abs(Math.round(n)).toLocaleString('en-US');}
function flash(el,dir){
  if(reduce)return;
  var c=dir>0?'t26-blot-row-fu':'t26-blot-row-fd';
  el.classList.remove('t26-blot-row-fu','t26-blot-row-fd');
  void el.offsetWidth;
  el.classList.add(c);
  window.setTimeout(function(){el.classList.remove(c);},700);
}
function paintPnl(r,dir){
  var px=parseFloat(r.dataset.px),q=parseFloat(r.dataset.qty),e=parseFloat(r.dataset.entry),sg=parseFloat(r.dataset.sign);
  var pnl=(px-e)*q*sg;
  r.dataset.pnl=pnl;
  var el=r.querySelector('.t26-blot-row-pnl');
  el.textContent=(pnl>=0?'▲ +':'▼ −')+money(pnl);
  el.classList.toggle('t26-blot-row-up',pnl>=0);
  el.classList.toggle('t26-blot-row-dn',pnl<0);
  if(dir)flash(el,dir);
}
function paintNet(){
  var s=0;rows.forEach(function(r){s+=parseFloat(r.dataset.pnl)||0;});
  netEl.textContent=(s>=0?'▲ +':'▼ −')+money(s);
  netEl.classList.toggle('t26-blot-row-up',s>=0);
  netEl.classList.toggle('t26-blot-row-dn',s<0);
}
rows.forEach(function(r){paintPnl(r,0);});
paintNet();
clock.textContent=clockTxt();
window.setInterval(function(){
  t+=1+Math.floor(Math.random()*2);
  clock.textContent=clockTxt();
  var r=rows[Math.floor(Math.random()*rows.length)];
  var px=parseFloat(r.dataset.px);
  var dir=Math.random()<0.52?1:-1;
  var np=Math.max(1,px+dir*(0.01+Math.random()*0.08));
  r.dataset.px=np.toFixed(2);
  var pxEl=r.querySelector('.t26-blot-row-px');
  pxEl.textContent=np.toFixed(2);
  flash(pxEl,dir);
  paintPnl(r,dir);
  paintNet();
},1150);

css:
.t26-fill-prog{
  --t26-fp-up:#3ddc97;--t26-fp-dn:#ff5d73;--t26-fp-acc:#6aa8ff;--t26-fp-dim:#79839b;
  --t26-fp-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  box-sizing:border-box;width:100%;padding:10px 11px;border-radius:10px;
  background:radial-gradient(120% 140% at 0% 0%,#171b28 0%,#0d1016 70%);
  border:1px solid rgba(255,255,255,.075);color:#e7ebf5;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  display:flex;flex-direction:column;gap:7px;
}
.t26-fill-prog-hd{display:flex;align-items:baseline;justify-content:space-between;font-size:9px;letter-spacing:.13em;color:var(--t26-fp-dim);}
.t26-fill-prog-ttl{font-weight:700;color:#aab3c7;}
.t26-fill-prog-sum{font-family:var(--t26-fp-mono);font-variant-numeric:tabular-nums;letter-spacing:.02em;}
.t26-fill-prog-dn{color:var(--t26-fp-up);font-weight:700;}
.t26-fill-prog-list{display:flex;flex-direction:column;gap:6px;}
.t26-fill-prog-it{display:flex;flex-direction:column;gap:3px;border-radius:5px;padding:1px 3px;outline:none;transition:background .18s ease;}
.t26-fill-prog-it:hover{background:rgba(255,255,255,.04);}
.t26-fill-prog-it:focus-visible{background:rgba(255,255,255,.06);box-shadow:0 0 0 1.5px var(--t26-fp-acc);}
.t26-fill-prog-l1{display:flex;align-items:center;gap:5px;font-size:10px;}
.t26-fill-prog-sd{display:inline-flex;align-items:center;justify-content:center;width:12px;height:12px;border-radius:3px;font-size:8px;font-weight:800;flex:none;}
.t26-fill-prog-b{background:rgba(61,220,151,.15);color:var(--t26-fp-up);box-shadow:inset 0 0 0 1px rgba(61,220,151,.3);}
.t26-fill-prog-s{background:rgba(255,93,115,.15);color:var(--t26-fp-dn);box-shadow:inset 0 0 0 1px rgba(255,93,115,.3);}
.t26-fill-prog-sym{font-weight:650;letter-spacing:.01em;}
.t26-fill-prog-ct{margin-left:auto;font-family:var(--t26-fp-mono);font-variant-numeric:tabular-nums;font-size:9.5px;color:#96a0b6;border-radius:3px;padding:0 2px;}
.t26-fill-prog-f{color:#e3e9f6;font-weight:600;}
.t26-fill-prog-pc{width:40px;text-align:right;font-family:var(--t26-fp-mono);font-variant-numeric:tabular-nums;font-size:9px;color:var(--t26-fp-acc);font-weight:700;letter-spacing:.02em;}
.t26-fill-prog-tr{position:relative;height:4px;border-radius:3px;background:rgba(255,255,255,.075);overflow:hidden;}
.t26-fill-prog-bar{position:absolute;inset:0 auto 0 0;width:0;border-radius:3px;background:linear-gradient(90deg,#3f7dd8,#6aa8ff);}
.t26-fill-prog-bar::after{content:"";position:absolute;top:0;bottom:0;left:0;width:34%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.34),transparent);transform:translateX(-110%);animation:t26-fill-prog-sh 1.8s linear infinite;}
.t26-fill-prog-full .t26-fill-prog-bar{background:linear-gradient(90deg,#2aa872,#3ddc97);}
.t26-fill-prog-full .t26-fill-prog-bar::after{animation:none;opacity:0;}
.t26-fill-prog-full .t26-fill-prog-pc{color:var(--t26-fp-up);}
.t26-fill-prog-full .t26-fill-prog-f{color:var(--t26-fp-up);}
.t26-fill-prog-tick{animation:t26-fill-prog-tick .65s ease-out;}
@keyframes t26-fill-prog-sh{0%{transform:translateX(-110%);}55%,100%{transform:translateX(330%);}}
@keyframes t26-fill-prog-tick{0%{background:rgba(106,168,255,.35);}100%{background:rgba(106,168,255,0);}}
@media (prefers-reduced-motion:reduce){
  .t26-fill-prog-bar::after{animation:none;opacity:0;}
  .t26-fill-prog-tick{animation:none;}
  .t26-fill-prog-it{transition:none;}
}

js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var items=Array.prototype.slice.call(root.querySelectorAll('.t26-fill-prog-it'));
var doneEl=root.querySelector('.t26-fill-prog-dn');
function countDone(){var n=0;items.forEach(function(i){if(parseFloat(i.dataset.cur)>=99.995)n++;});doneEl.textContent=n;}
function render(it,pct){
  var total=parseFloat(it.dataset.total);
  it.querySelector('.t26-fill-prog-bar').style.width=pct.toFixed(2)+'%';
  it.querySelector('.t26-fill-prog-f').textContent=Math.round(total*pct/100).toLocaleString('en-US');
  var pc=it.querySelector('.t26-fill-prog-pc');
  if(pct>=99.995){it.classList.add('t26-fill-prog-full');pc.textContent='FILLED';}
  else{it.classList.remove('t26-fill-prog-full');pc.textContent=Math.floor(pct)+'%';}
  it.dataset.cur=pct;
  countDone();
}
function animate(it,from,to,dur,delay){
  var tok=(parseInt(it.dataset.tok||'0',10)+1);
  it.dataset.tok=tok;
  if(reduce){window.setTimeout(function(){if(+it.dataset.tok===tok){render(it,to);it.dataset.done='1';}},delay);return;}
  var start=null;
  function step(ts){
    if(+it.dataset.tok!==tok)return;
    if(start===null)start=ts;
    var p=Math.min(1,(ts-start)/dur);
    render(it,from+(to-from)*(1-Math.pow(1-p,3)));
    if(p<1){window.requestAnimationFrame(step);}else{it.dataset.done='1';}
  }
  window.setTimeout(function(){window.requestAnimationFrame(step);},delay);
}
items.forEach(function(it,i){it.dataset.cur=0;it.dataset.done='';render(it,0);animate(it,0,parseFloat(it.dataset.tgt),1300,160+i*170);});
window.setInterval(function(){
  var ready=items.filter(function(i){return i.dataset.done==='1';});
  if(!ready.length)return;
  var open=ready.filter(function(i){return parseFloat(i.dataset.cur)<99.995;});
  if(!open.length){
    var re=ready[Math.floor(Math.random()*ready.length)];
    re.dataset.done='';render(re,0);
    animate(re,0,8+Math.random()*24,900,0);
    return;
  }
  var it=open[Math.floor(Math.random()*open.length)];
  var cur=parseFloat(it.dataset.cur);
  var to=cur+3+Math.random()*9;
  it.dataset.done='';
  animate(it,cur,to>95?100:to,700,0);
  var ct=it.querySelector('.t26-fill-prog-ct');
  if(!reduce){ct.classList.remove('t26-fill-prog-tick');void ct.offsetWidth;ct.classList.add('t26-fill-prog-tick');}
},2600);

css:
.t26-ord-timeline{
  --t26-ot-up:#3ddc97;--t26-ot-acc:#6aa8ff;--t26-ot-dim:#79839b;
  --t26-ot-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  box-sizing:border-box;width:100%;padding:12px 12px;border-radius:10px;
  background:linear-gradient(180deg,#151927 0%,#0c0f16 100%);
  border:1px solid rgba(255,255,255,.075);color:#e7ebf5;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  display:flex;flex-direction:column;gap:2px;transition:box-shadow .5s ease;
}
.t26-ord-timeline-cmp{box-shadow:inset 0 0 0 1px rgba(61,220,151,.28);}
.t26-ord-timeline-hd{display:flex;align-items:baseline;justify-content:space-between;font-size:9px;color:var(--t26-ot-dim);}
.t26-ord-timeline-oid{font-family:var(--t26-ot-mono);font-variant-numeric:tabular-nums;letter-spacing:.08em;color:#aab3c7;font-weight:700;}
.t26-ord-timeline-meta{font-size:8.5px;letter-spacing:.02em;}
.t26-ord-timeline-track{position:relative;padding:16px 0 6px;}
.t26-ord-timeline-rail{position:absolute;left:16px;right:16px;top:21px;height:2px;border-radius:2px;background:rgba(255,255,255,.09);overflow:hidden;}
.t26-ord-timeline-fill{display:block;height:100%;width:0;border-radius:2px;background:linear-gradient(90deg,#3ddc97,#6aa8ff);transition:width .75s cubic-bezier(.65,0,.35,1);}
.t26-ord-timeline-steps{position:relative;display:flex;justify-content:space-between;}
.t26-ord-timeline-st{appearance:none;-webkit-appearance:none;background:none;border:0;padding:0;margin:0;font:inherit;color:inherit;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:5px;width:56px;border-radius:6px;outline:none;}
.t26-ord-timeline-st:focus-visible{box-shadow:0 0 0 1.5px var(--t26-ot-acc);}
.t26-ord-timeline-dot{position:relative;display:flex;align-items:center;justify-content:center;width:11px;height:11px;border-radius:50%;box-sizing:border-box;background:#0d1017;border:2px solid rgba(255,255,255,.22);transition:border-color .3s ease,background .3s ease,transform .3s cubic-bezier(.34,1.56,.64,1);}
.t26-ord-timeline-done .t26-ord-timeline-dot{background:var(--t26-ot-up);border-color:var(--t26-ot-up);}
.t26-ord-timeline-done .t26-ord-timeline-dot::after{content:"";width:2px;height:5px;border-right:1.6px solid #06170f;border-bottom:1.6px solid #06170f;transform:translateY(-1px) rotate(42deg);}
.t26-ord-timeline-on .t26-ord-timeline-dot{background:#0d1017;border-color:var(--t26-ot-acc);transform:scale(1.25);animation:t26-ord-timeline-ring 1.6s ease-out infinite;}
.t26-ord-timeline-lb{font-size:8px;letter-spacing:.1em;color:#5f6980;transition:color .3s ease;}
.t26-ord-timeline-done .t26-ord-timeline-lb{color:#8f9bb2;}
.t26-ord-timeline-on .t26-ord-timeline-lb{color:#eaf0ff;font-weight:700;}
.t26-ord-timeline-detail{display:flex;align-items:baseline;gap:7px;margin-top:6px;padding:6px 7px;border-radius:6px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.05);}
.t26-ord-timeline-ts{font-family:var(--t26-ot-mono);font-variant-numeric:tabular-nums;font-size:9px;color:var(--t26-ot-acc);letter-spacing:.02em;flex:none;}
.t26-ord-timeline-msg{font-size:9px;color:#b6bfd2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.t26-ord-timeline-swap{animation:t26-ord-timeline-swap .42s cubic-bezier(.22,1,.36,1);}
@keyframes t26-ord-timeline-ring{0%{box-shadow:0 0 0 0 rgba(106,168,255,.45);}70%{box-shadow:0 0 0 7px rgba(106,168,255,0);}100%{box-shadow:0 0 0 0 rgba(106,168,255,0);}}
@keyframes t26-ord-timeline-swap{0%{opacity:0;transform:translateY(4px);}100%{opacity:1;transform:translateY(0);}}
@media (prefers-reduced-motion:reduce){
  .t26-ord-timeline-fill{transition:none;}
  .t26-ord-timeline-on .t26-ord-timeline-dot{animation:none;}
  .t26-ord-timeline-swap{animation:none;}
  .t26-ord-timeline-dot{transition:none;}
}

js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var steps=Array.prototype.slice.call(root.querySelectorAll('.t26-ord-timeline-st'));
var fill=root.querySelector('.t26-ord-timeline-fill');
var tsEl=root.querySelector('.t26-ord-timeline-ts');
var msgEl=root.querySelector('.t26-ord-timeline-msg');
var detail=root.querySelector('.t26-ord-timeline-detail');
var cur=-1,timer=null,auto=true;
function show(i){
  cur=i;
  steps.forEach(function(s,k){
    s.classList.toggle('t26-ord-timeline-done',k<i);
    s.classList.toggle('t26-ord-timeline-on',k===i);
    if(k===i){s.setAttribute('aria-current','step');}else{s.removeAttribute('aria-current');}
  });
  fill.style.width=(i<=0?0:(i/(steps.length-1))*100)+'%';
  tsEl.textContent=steps[i].dataset.ts;
  msgEl.textContent=steps[i].dataset.msg;
  root.classList.toggle('t26-ord-timeline-cmp',i===steps.length-1);
  if(!reduce){detail.classList.remove('t26-ord-timeline-swap');void detail.offsetWidth;detail.classList.add('t26-ord-timeline-swap');}
}
function loop(){
  window.clearTimeout(timer);
  if(!auto)return;
  var n=cur+1,wait;
  if(n>=steps.length){show(0);wait=1350;}
  else{show(n);wait=(n===steps.length-1)?2900:1350;}
  timer=window.setTimeout(loop,wait);
}
steps.forEach(function(s,i){
  s.addEventListener('click',function(){auto=false;window.clearTimeout(timer);show(i);});
});
show(0);
timer=window.setTimeout(loop,1350);

css:
.t26-exq-score{
  --t26-eq-up:#3ddc97;--t26-eq-dn:#ff5d73;--t26-eq-acc:#6aa8ff;--t26-eq-dim:#79839b;
  --t26-eq-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  box-sizing:border-box;width:100%;padding:13px 12px;border-radius:10px;
  background:linear-gradient(135deg,#161b28 0%,#0c0f16 65%);
  border:1px solid rgba(255,255,255,.075);color:#e7ebf5;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  display:flex;align-items:center;gap:11px;
}
.t26-exq-score-ring{position:relative;width:88px;height:88px;flex:none;display:flex;align-items:center;justify-content:center;}
.t26-exq-score-svg{position:absolute;inset:0;width:88px;height:88px;}
.t26-exq-score-tr{fill:none;stroke:rgba(255,255,255,.08);stroke-width:6;}
.t26-exq-score-ar{fill:none;stroke:#3ddc97;stroke-width:6;stroke-linecap:round;transform:rotate(-90deg);transform-origin:42px 42px;transition:stroke-dashoffset 1.15s cubic-bezier(.22,1,.36,1);}
.t26-exq-score-num{font-family:var(--t26-eq-mono);font-variant-numeric:tabular-nums;font-size:24px;font-weight:700;line-height:1;letter-spacing:-.02em;color:#f0f4ff;transform:translateY(-4px);}
.t26-exq-score-gr{position:absolute;bottom:21px;font-size:8px;letter-spacing:.14em;color:var(--t26-eq-up);font-weight:700;}
.t26-exq-score-body{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:7px;}
.t26-exq-score-hd{display:flex;align-items:center;gap:5px;font-size:8.5px;letter-spacing:.12em;color:#aab3c7;font-weight:700;}
.t26-exq-score-win{color:#5f6980;font-weight:600;letter-spacing:.06em;}
