js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var C=2*Math.PI*35,SCORE=87;
var arc=root.querySelector('.t26-exq-score-ar');
var numEl=root.querySelector('.t26-exq-score-num');
var metrics=Array.prototype.slice.call(root.querySelectorAll('.t26-exq-score-m'));
var btn=root.querySelector('.t26-exq-score-rerun');
arc.style.strokeDasharray=C.toFixed(2);
arc.style.strokeDashoffset=C.toFixed(2);
function count(el,to,dec,pre,suf,dur){
  if(reduce){el.textContent=pre+Math.abs(to).toFixed(dec)+suf;return;}
  var start=null;
  function step(ts){
    if(start===null)start=ts;
    var p=Math.min(1,(ts-start)/dur);
    el.textContent=pre+Math.abs(to*(1-Math.pow(1-p,3))).toFixed(dec)+suf;
    if(p<1)window.requestAnimationFrame(step);
  }
  window.requestAnimationFrame(step);
}
function run(){
  arc.style.strokeDashoffset=C.toFixed(2);
  metrics.forEach(function(m){m.querySelector('.t26-exq-score-fl').style.width='0%';});
  window.setTimeout(function(){
    arc.style.strokeDashoffset=(C*(1-SCORE/100)).toFixed(2);
    count(numEl,SCORE,0,'','',1100);
    metrics.forEach(function(m,i){
      window.setTimeout(function(){m.querySelector('.t26-exq-score-fl').style.width=m.dataset.w+'%';},i*110);
      count(m.querySelector('.t26-exq-score-v'),parseFloat(m.dataset.n),parseInt(m.dataset.dec,10),m.dataset.pre,m.dataset.suf,1000);
    });
  },reduce?0:70);
}
btn.addEventListener('click',run);
run();

