js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var qtyEl=root.querySelector('.t26-cxl-replace-vqty');
var pxEl=root.querySelector('.t26-cxl-replace-vpx');
var msg=root.querySelector('.t26-cxl-replace-msg');
var st=root.querySelector('.t26-cxl-replace-st');
var rep=root.querySelector('.t26-cxl-replace-rep');
var cxl=root.querySelector('.t26-cxl-replace-cxl');
var fillEl=root.querySelector('.t26-cxl-replace-fill');
var ctx=root.querySelector('.t26-cxl-replace-ctx');
var steppers=Array.prototype.slice.call(root.querySelectorAll('.t26-cxl-replace-sb'));
var HOLD=850,clock=34272;
var base={q:2500,p:118.40},cur={q:2500,p:118.40};
var live=true,busy=false,holdT=null;
function two(n){return n<10?'0'+n:''+n;}
function tstamp(){clock+=2+Math.floor(Math.random()*4);var h=Math.floor(clock/3600)%24,m=Math.floor(clock/60)%60,s=clock%60;return two(h)+':'+two(m)+':'+two(s);}
function fq(n){return n.toLocaleString('en-US');}
function setStatus(kind,label){
  st.className='t26-cxl-replace-st'+(kind?' t26-cxl-replace-st-'+kind:'');
  st.textContent=label;
}
function dirty(){return cur.q!==base.q||Math.abs(cur.p-base.p)>0.001;}
function paint(){
  qtyEl.textContent=fq(cur.q);
  pxEl.textContent=cur.p.toFixed(2);
  qtyEl.classList.toggle('t26-cxl-replace-chg',cur.q!==base.q);
  pxEl.classList.toggle('t26-cxl-replace-chg',Math.abs(cur.p-base.p)>0.001);
  rep.disabled=!dirty()||!live||busy;
  steppers.forEach(function(b){b.disabled=!live||busy;});
  if(busy)return;
  if(dirty()){
    var parts=[];
    if(cur.q!==base.q)parts.push('qty '+(cur.q>base.q?'+':'−')+fq(Math.abs(cur.q-base.q)));
    if(Math.abs(cur.p-base.p)>0.001)parts.push('px '+(cur.p>base.p?'▲ +':'▼ −')+Math.abs(cur.p-base.p).toFixed(2));
    msg.textContent='Δ '+parts.join(' · ')+' — ready to send';
    msg.className='t26-cxl-replace-msg t26-cxl-replace-m-amend';
  }else if(live){
    msg.textContent='Amend qty or limit to enable replace';
    msg.className='t26-cxl-replace-msg';
  }
}
steppers.forEach(function(b){
  b.addEventListener('click',function(){
    if(!live||busy)return;
    var d=parseInt(b.dataset.d,10);
    if(b.dataset.k==='qty'){cur.q=Math.max(100,cur.q+d*100);}
    else{cur.p=Math.max(0.05,Math.round((cur.p+d*0.05)*100)/100);}
    paint();
    var v=b.dataset.k==='qty'?qtyEl:pxEl;
    if(!reduce){v.classList.remove('t26-cxl-replace-bump');void v.offsetWidth;v.classList.add('t26-cxl-replace-bump');}
  });
});
rep.addEventListener('click',function(){
  if(rep.disabled)return;
  busy=true;paint();
  root.classList.add('t26-cxl-replace-pending');
  setStatus('PENDING','PENDING REPL');
  rep.textContent='SENDING';
  msg.textContent='Replace sent · awaiting venue ack';
  msg.className='t26-cxl-replace-msg';
  window.setTimeout(function(){
    var oq=base.q,op=base.p;
    base={q:cur.q,p:cur.p};
    root.classList.remove('t26-cxl-replace-pending');
    setStatus('OK','REPLACED');
    rep.textContent='REPLACE';
    busy=false;paint();
    msg.textContent=tstamp()+' · '+fq(oq)+'→'+fq(base.q)+' @ '+op.toFixed(2)+'→'+base.p.toFixed(2);
    msg.className='t26-cxl-replace-msg t26-cxl-replace-m-ok';
    if(!reduce){[qtyEl,pxEl].forEach(function(el){el.classList.remove('t26-cxl-replace-ok');void el.offsetWidth;el.classList.add('t26-cxl-replace-ok');});}
    window.setTimeout(function(){if(live&&!busy)setStatus('','WORKING');},1700);
  },950);
});
function startHold(){
  if(!live||busy||holdT)return;
  root.classList.add('t26-cxl-replace-holding');
  fillEl.style.transitionDuration=HOLD+'ms';
  fillEl.style.width='100%';
  ctx.textContent='KEEP HOLDING';
  holdT=window.setTimeout(doCancel,HOLD);
}
function endHold(){
  if(!holdT)return;
  window.clearTimeout(holdT);holdT=null;
  root.classList.remove('t26-cxl-replace-holding');
  fillEl.style.transitionDuration='170ms';
  fillEl.style.width='0%';
  ctx.textContent='HOLD TO CANCEL';
}
function doCancel(){
  holdT=null;live=false;busy=false;
  root.classList.remove('t26-cxl-replace-holding');
  setStatus('CXL','CANCELED');
  ctx.textContent='CANCELED';
  fillEl.style.width='100%';
  paint();
  msg.textContent=tstamp()+' · canceled · '+fq(cur.q)+' unfilled';
  msg.className='t26-cxl-replace-msg t26-cxl-replace-m-cxl';
  window.setTimeout(reset,2800);
}
function reset(){
  live=true;base={q:2500,p:118.40};cur={q:2500,p:118.40};
  fillEl.style.transitionDuration='170ms';fillEl.style.width='0%';
  ctx.textContent='HOLD TO CANCEL';
  setStatus('','WORKING');
  paint();
}
cxl.addEventListener('pointerdown',startHold);
cxl.addEventListener('pointerup',endHold);
cxl.addEventListener('pointerleave',endHold);
cxl.addEventListener('pointercancel',endHold);
cxl.addEventListener('keydown',function(e){if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();startHold();}});
cxl.addEventListener('keyup',function(e){if(e.key===' '||e.key==='Enter'){e.preventDefault();endHold();}});
cxl.addEventListener('click',function(e){e.preventDefault();});
paint();

