var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var S={
 pend:{lb:'PENDING NEW',ic:'◷',q:'0 / 900',sub:'ORD 8841-QX · sent 09:31:02.114'},
 'new':{lb:'NEW · ACKED',ic:'●',q:'0 / 900',sub:'venue ack 09:31:02.331 · NSDQ'},
 part:{lb:'PARTIAL FILL',ic:'◑',q:'620 / 900',sub:'last 09:31:04.882 @ 248.16'},
 fill:{lb:'FILLED',ic:'✓',q:'900 / 900',sub:'avg 248.1420 · slip ▼ −0.6bp'},
 repl:{lb:'REPLACED',ic:'⇄',q:'900 → 1,100',sub:'amend acked 09:31:05.010'},
 cxl:{lb:'CANCELED',ic:'✕',q:'620 / 900',sub:'cxl 09:31:09.740 · 280 unfilled'},
 rej:{lb:'REJECTED',ic:'⊘',q:'0 / 900',sub:'reason 3040 · price band breach'},
 exp:{lb:'EXPIRED',ic:'◌',q:'340 / 900',sub:'DAY order · expired 16:00:00'}
};
var order=['pend','new','part','fill','repl','cxl','rej','exp'];
var live=root.querySelector('.t26-life-badge-live');
var icon=root.querySelector('.t26-life-badge-icon');
var state=root.querySelector('.t26-life-badge-state');
var sub=root.querySelector('.t26-life-badge-sub');
var qty=root.querySelector('.t26-life-badge-qty');
var btns=Array.prototype.slice.call(root.querySelectorAll('.t26-life-badge-b'));
var idx=1,auto=true,timer=null;
function setState(k){
  var s=S[k];if(!s)return;
  live.className='t26-life-badge-live t26-life-badge-s-'+k;
  icon.textContent=s.ic;state.textContent=s.lb;sub.textContent=s.sub;qty.textContent=s.q;
  if(!reduce){live.classList.remove('t26-life-badge-swap');void live.offsetWidth;live.classList.add('t26-life-badge-swap');}
  btns.forEach(function(b){
    var on=b.dataset.s===k;
    b.classList.toggle('t26-life-badge-on',on);
    b.setAttribute('aria-pressed',on?'true':'false');
  });
}
btns.forEach(function(b){
  b.addEventListener('click',function(){auto=false;window.clearTimeout(timer);setState(b.dataset.s);});
});
function step(){
  if(!auto)return;
  setState(order[idx%order.length]);idx++;
  timer=window.setTimeout(step,1900);
}
setState('pend');
timer=window.setTimeout(step,1300);

