var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var groups=Array.prototype.slice.call(root.querySelectorAll('.t26-grp-fills-g'));
function setOpen(g,open){
  var legs=g.querySelector('.t26-grp-fills-legs');
  var btn=g.querySelector('.t26-grp-fills-p');
  g.classList.toggle('t26-grp-fills-open',open);
  btn.setAttribute('aria-expanded',open?'true':'false');
  legs.style.maxHeight=open?legs.scrollHeight+'px':'0px';
}
groups.forEach(function(g){
  setOpen(g,false);
  g.querySelector('.t26-grp-fills-p').addEventListener('click',function(){
    var was=g.classList.contains('t26-grp-fills-open');
    groups.forEach(function(o){setOpen(o,false);});
    if(!was)setOpen(g,true);
  });
});
window.addEventListener('resize',function(){
  groups.forEach(function(g){
    if(g.classList.contains('t26-grp-fills-open')){
      g.querySelector('.t26-grp-fills-legs').style.maxHeight=g.querySelector('.t26-grp-fills-legs').scrollHeight+'px';
    }
  });
});
window.setTimeout(function(){setOpen(groups[0],true);},reduce?0:480);
